package netcheck

import (
	"context"
	"errors"
	"fmt"
	"net"
	"strings"
)

// runResolve answers what the target's name maps to, or what its address maps
// back to. Exactly one of the two questions has meaning for a given target,
// and the other says so rather than being absent.
func runResolve(ctx context.Context, t Target, env Env, _ Settings, _ *Results) []Check {
	if ip := net.ParseIP(strings.TrimSpace(t.Host)); ip != nil {
		return []Check{
			literalAddress(ip),
			reverseLookup(ctx, t, env, ip.String()),
		}
	}
	return []Check{
		forwardLookup(ctx, t, env),
		newCheck(CheckReverseDNS, StageResolve, NotApplicable,
			"Target is a name, not an address"),
	}
}

// concludeResolveBehindProxy is a compile-only skeleton (DEVDESK-596, red phase).
func concludeResolveBehindProxy(_ Target, _ *Results) {}

// forwardLookup resolves a name.
func forwardLookup(ctx context.Context, t Target, env Env) Check {
	ips, err := env.Resolve(ctx, t.Host, t.Resolver)
	c := newCheck(CheckResolve, StageResolve, Fail, "")
	c.fact("Resolver", resolverLabel(t.Resolver))

	if err != nil {
		c.Summary = fmt.Sprintf("%s does not resolve", t.Host)
		c.fact("Error", err.Error())
		if dnsErr, ok := serverMisbehaved(err); ok {
			c.Reason = ReasonServerMisbehaving
			c.fact("Temporary", temporaryLabel(dnsErr.IsTemporary))
		}
		return c
	}
	if len(ips) == 0 {
		c.Summary = fmt.Sprintf("%s resolves to no address", t.Host)
		return c
	}

	c.Verdict = OK
	if len(ips) == 1 {
		c.Summary = fmt.Sprintf("%s resolves to %s (%s)", t.Host, ips[0], addressClass(ips[0]))
	} else {
		c.Summary = fmt.Sprintf("%s resolves to %d addresses", t.Host, len(ips))
	}
	for _, ip := range ips {
		c.fact("Address", fmt.Sprintf("%s (%s)", ip, addressClass(ip)))
	}
	return c
}

// literalAddress records that no resolution was needed. It is NotApplicable
// with no Because: the question has no meaning here, which is a different
// thing from having been blocked.
func literalAddress(ip net.IP) Check {
	c := newCheck(CheckResolve, StageResolve, NotApplicable,
		"Target is a literal address, no resolution needed")
	c.fact("Address", fmt.Sprintf("%s (%s)", ip, addressClass(ip)))
	return c
}

// reverseLookup asks what an address maps back to.
//
// A missing PTR record is a Warn and never a Fail: plenty of reachable hosts
// have none, and the objective this package serves does not depend on it.
func reverseLookup(ctx context.Context, t Target, env Env, ip string) Check {
	names, err := env.ReverseLookup(ctx, ip, t.Resolver)
	c := newCheck(CheckReverseDNS, StageResolve, Warn, "")
	c.fact("Resolver", resolverLabel(t.Resolver))

	switch {
	case err != nil:
		c.Summary = fmt.Sprintf("%s has no reverse record", ip)
		c.fact("Error", err.Error())
	case len(names) == 0:
		c.Summary = fmt.Sprintf("%s has no reverse record", ip)
	default:
		c.Verdict = OK
		c.Summary = fmt.Sprintf("%s resolves back to %s", ip, strings.TrimSuffix(names[0], "."))
		for _, n := range names {
			c.fact("Name", strings.TrimSuffix(n, "."))
		}
	}
	return c
}

// resolverLabel names the resolver a lookup used. "System resolver" is not a
// placeholder: it is the answer the user cares about, because it is the one
// their own traffic will use.
func resolverLabel(resolver string) string {
	if strings.TrimSpace(resolver) == "" {
		return "System resolver"
	}
	return resolver
}

// serverMisbehaved reports whether err is Go's net.DNSError for a resolver
// that answered with something the client could not use — the exact wording
// ("server misbehaving") is unexported in net, so this matches the DNSError
// field it sets rather than the formatted string, the same way stage_tls.go
// matches tls.RecordHeaderError instead of grepping an error message.
func serverMisbehaved(err error) (*net.DNSError, bool) {
	var dnsErr *net.DNSError
	if errors.As(err, &dnsErr) && dnsErr.Err == "server misbehaving" {
		return dnsErr, true
	}
	return nil, false
}

// temporaryLabel names the one bit "server misbehaving" leaves out of its own
// text: whether the response's code was SERVFAIL (IsTemporary — a transient
// problem, worth a retry) or anything else Go's client will not accept
// (FORMERR, REFUSED, an unsupported EDNS version...), which does not go away
// on its own.
func temporaryLabel(temporary bool) string {
	if temporary {
		return "Yes — a SERVFAIL response, usually transient"
	}
	return "No — the server actively rejected or could not parse the query"
}

// addressClass names the family an address belongs to.
//
// The class is what the diagnosis rests on — private or public, routable or
// not — never the literal octets. It is also what survives pseudonymisation if
// a payload is ever built from these checks.
func addressClass(ip net.IP) string {
	switch {
	case ip.IsLoopback():
		return "loopback"
	case ip.IsLinkLocalUnicast(), ip.IsLinkLocalMulticast():
		return "link-local"
	case ip.IsPrivate():
		return "private"
	case ip.IsUnspecified():
		return "unspecified"
	case ip.To4() == nil:
		return "public IPv6"
	default:
		return "public"
	}
}

package netcheck

import (
	"context"
	"errors"
	"net"
	"net/url"
	"reflect"
	"slices"
	"testing"

	"github.com/anthnel/devdesk/internal/netproxy"
)

// DEVDESK-596: when the direct lookup of a named target fails and the Proxy row
// says a proxy applies, the DNS row is rewritten in place once the Proxy stage
// has run. Behind a mandatory proxy the name is often resolved by the proxy, so
// "does not resolve" alone would mislead. The Proxy stage keeps its place in the
// pipeline; it concludes on the earlier DNS row through stage.conclude.

const (
	resolveGenericSummary = "example.com does not resolve"
	resolveProxySummary   = "example.com does not resolve directly; a proxy is configured for this target"
	proxyDisplay          = "http://proxy.corp:3128"
)

func resolveFailing(err error) func(context.Context, string, string) ([]net.IP, error) {
	return func(context.Context, string, string) ([]net.IP, error) { return nil, err }
}

func resolveEmpty(context.Context, string, string) ([]net.IP, error) { return nil, nil }

var errNoSuchHost = errors.New("no such host")

// misbehavingErr is the DNS error that keeps its own reason.
func misbehavingErr() *net.DNSError {
	return &net.DNSError{Err: "server misbehaving", Name: "example.com", IsTemporary: true}
}

// resolveRowOf returns the DNS row of a finished run.
func resolveRowOf(t *testing.T, res Results) Check {
	t.Helper()
	return checkNamed(t, res.All(), CheckResolve)
}

func runAll(t *testing.T, env Env, tg Target) Results {
	t.Helper()
	res, err := Run(context.Background(), tg, env, DefaultSettings())
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	return res
}

// chain runs every stage through RunStep, the way a view does.
func chain(env Env, tg Target) Results {
	var res Results
	for _, id := range Steps() {
		res = RunStep(context.Background(), tg, env, DefaultSettings(), id, res)
	}
	return res
}

func TestTheDirectResolveReasonIdentifierIsStable(t *testing.T) {
	if got := string(ReasonDirectResolveFailedProxyConfigured); got != "direct-resolve-failed-proxy-configured" {
		t.Errorf("identifier = %q, want %q: MCP serializes it", got, "direct-resolve-failed-proxy-configured")
	}
}

// Every way the Proxy row reads "configured" rewrites a failed lookup the same
// way. The Proxy fact is the displayed proxy only (https first), the Resolver and
// Error facts are kept, and the verdict stays Fail: the direct lookup did fail.
func TestAFailedResolutionWithAProxyConfiguredSaysSo(t *testing.T) {
	for _, tc := range []struct {
		name     string
		resolve  func(context.Context, string, string) ([]net.IP, error)
		resolver string
		proxy    func(*url.URL) netproxy.Decision
		want     []Fact
	}{
		{"an unknown name", resolveFailing(errNoSuchHost), "", proxiedBoth,
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
		{"an empty answer carries no error fact", resolveEmpty, "", proxiedBoth,
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}}},
		{"a proxy for https only", resolveFailing(errNoSuchHost), "", perScheme(
			decided(netproxy.DecisionProxied, "HTTPS_PROXY", proxyDisplay), none()),
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
		{"a proxy for http only", resolveFailing(errNoSuchHost), "", perScheme(
			none(), decided(netproxy.DecisionProxied, "http_proxy", proxyDisplay)),
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
		{"two different proxys: the https one", resolveFailing(errNoSuchHost), "", perScheme(
			decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://a:3128"),
			decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://b:8080")),
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", "http://a:3128"}, {"Error", "no such host"}}},
		{"a proxy outranks an exclusion on the other scheme", resolveFailing(errNoSuchHost), "", perScheme(
			decided(netproxy.DecisionExcluded, "HTTPS_PROXY", ""),
			decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://b:8080")),
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", "http://b:8080"}, {"Error", "no such host"}}},
		{"a proxy outranks loopback on the other scheme", resolveFailing(errNoSuchHost), "", perScheme(
			decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://a:3128"),
			decided(netproxy.DecisionLoopback, "HTTP_PROXY", "")),
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", "http://a:3128"}, {"Error", "no such host"}}},
		{"an invalid variable and a proxied scheme still name the proxy", resolveFailing(errNoSuchHost), "", perScheme(
			decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""),
			decided(netproxy.DecisionProxied, "HTTP_PROXY", proxyDisplay)),
			[]Fact{{"Resolver", "System resolver"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
		{"a named resolver is kept", resolveFailing(errNoSuchHost), "9.9.9.9", proxiedBoth,
			[]Fact{{"Resolver", "9.9.9.9"}, {"Proxy", proxyDisplay}, {"Error", "no such host"}}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			tg := Target{Host: "example.com", Port: 443, Resolver: tc.resolver}
			res := runAll(t, fakeEnv{resolve: tc.resolve, proxy: tc.proxy}, tg)

			// The premise: the Proxy row reads that a proxy applies.
			if p := checkNamed(t, res.All(), CheckProxy); p.Proxy == "" {
				t.Fatalf("premise: the proxy row names no proxy (reason %q)", p.Reason)
			}

			c := resolveRowOf(t, res)
			if c.Summary != resolveProxySummary {
				t.Errorf("summary = %q, want %q", c.Summary, resolveProxySummary)
			}
			if c.Verdict != Fail {
				t.Errorf("verdict = %v, want Fail: the direct lookup did fail", c.Verdict)
			}
			if c.Reason != ReasonDirectResolveFailedProxyConfigured {
				t.Errorf("reason = %q, want %q", c.Reason, ReasonDirectResolveFailedProxyConfigured)
			}
			if !slices.Equal(c.Facts, tc.want) {
				t.Errorf("facts = %v, want %v", c.Facts, tc.want)
			}
			if c.ID != CheckResolve || c.Stage != StageResolve || c.Title != "DNS resolution" {
				t.Errorf("identity = %s/%s/%q, want the row's own", c.ID, c.Stage, c.Title)
			}
		})
	}
}

// Without a proxy that applies, the DNS row is what it was before: strictly the
// row of a run in which no proxy variable exists.
func TestAFailedResolutionWithoutAProxyIsUnchanged(t *testing.T) {
	failures := []struct {
		name    string
		resolve func(context.Context, string, string) ([]net.IP, error)
	}{
		{"an unknown name", resolveFailing(errNoSuchHost)},
		{"an empty answer", resolveEmpty},
		{"a misbehaving resolver", resolveFailing(misbehavingErr())},
	}
	for _, tc := range []struct {

package netcheck

import (
	"context"
	"errors"
)

// errNotTLSConn is returned when a dialer hands back something that is not a
// TLS connection. It cannot happen with tls.Dialer, and is reported rather
// than asserted so a future dialer swap fails loudly.
var errNotTLSConn = errors.New("connection is not a TLS connection")

// checkTitles is the one place a check's human name is written. The skip path
// needs a title for a check that never ran, so it cannot come from the stage
// that would have produced it.
var checkTitles = map[CheckID]string{
	CheckResolve:      "DNS resolution",
	CheckReverseDNS:   "Reverse DNS",
	CheckRoute:        "Local route",
	CheckICMP:         "ICMP echo",
	CheckProxy:        "Proxy",
	CheckTCP:          "TCP connect",
	CheckTLSHandshake: "TLS handshake",
	CheckTLSChain:     "Certificate chain",
	CheckTLSHostname:  "Hostname match",
	CheckTLSExpiry:    "Certificate expiry",
	CheckTLSVersion:   "TLS version",
	CheckHTTP:         "HTTP response",
}

// stage is one layer of the pipeline.
type stage struct {
	id        StageID
	dependsOn StageID
	// gate is the check whose verdict decides whether dependent stages run.
	// A stage that gates nothing leaves it empty — which is a decision, not an
	// omission, at both sites that use it.
	gate CheckID
	// produces is what run returns, declared so the skip path can name the
	// checks that never ran. TestEveryStageProducesWhatItDeclares keeps the two
	// in step.
	produces []CheckID
	run      func(ctx context.Context, t Target, env Env, set Settings, prior *Results) []Check
	// amends names the checks of earlier stages that conclude may rewrite.
	amends []CheckID
	// conclude runs after the stage's own checks are added, only when the stage
	// really ran.
	conclude func(t Target, res *Results)
}

// stageTitles names a stage for a progress line. A stage is what the user waits
// on, so it is what the wait is labelled with.
var stageTitles = map[StageID]string{
	StageResolve: "Resolving the name",
	StageRoute:   "Finding the way out",
	StageReach:   "Probing reachability",
	StageProxy:   "Reading the proxy settings",
	StageConnect: "Connecting to the port",
	StageTLS:     "Inspecting the certificate",
	StageHTTP:    "Asking for a response",
}

// StageTitle names a stage, for a caller reporting progress.
func StageTitle(id StageID) string { return stageTitles[id] }

// Steps returns the pipeline in order.
//
// It exists so an interactive caller can run one stage at a time and say which
// question is being asked. That matters most in the case worth diagnosing: an
// unreachable host spends its timeouts one after another, and a spinner with
// nothing beside it is indistinguishable from a hang — §3.16's lesson.
func Steps() []StageID {
	all := stages()
	out := make([]StageID, 0, len(all))
	for _, s := range all {
		out = append(out, s.id)
	}
	return out
}

// RunStep runs one stage against the results so far and returns the updated
// set. It applies the same skip rule Run does — there is one cascade, not two.
//
// prior is never modified: the returned Results is built from a copy, so a
// caller may hold the previous value across a goroutine boundary without
// sharing anything with this call. That is what lets a Bubble Tea view chain
// the stages through messages and never touch a model from inside a Cmd
// (Rule 110).
func RunStep(ctx context.Context, t Target, env Env, set Settings, id StageID, prior Results) Results {
	res := prior.clone()
	set = set.Normalized()
	all := stages()
	gateOf := gatesOf(all)

	for _, s := range all {
		if s.id != id {
			continue
		}
		runStage(ctx, s, gateOf, t, env, set, &res)
	}
	return res
}

// stages is the pipeline, in order.
//
// Two of the dependencies are worth reading twice:
//
//   - reach gates nothing. ICMP is filtered on a large share of hosts that are
//     perfectly reachable, so a silent ping must not cascade NotApplicable over
//     the TLS checks — which is the whole question the user came to ask.
//   - proxy depends on nothing and gates nothing: it reads the environment, so
//     it is there even when the DNS fails, which is the common case behind a
//     mandatory proxy.
//   - http depends on connect, not on tls. A broken chain must not hide whether
//     the service answers: "the app works, the certificate is what is wrong" is
//     useful, and the certificate problem has rows of its own.
func stages() []stage {
	return []stage{
		{
			id:       StageResolve,
			gate:     CheckResolve,
			produces: []CheckID{CheckResolve, CheckReverseDNS},
			run:      runResolve,
		},
		{
			id:        StageRoute,
			dependsOn: StageResolve,
			produces:  []CheckID{CheckRoute},
			run:       runRoute,
		},
		{
			id:        StageReach,
			dependsOn: StageResolve,
			produces:  []CheckID{CheckICMP},
			run:       runReach,
		},
		{
			id:       StageProxy,
			produces: []CheckID{CheckProxy},
			run:      runProxy,
		},
		{
			id:        StageConnect,
			dependsOn: StageResolve,
			gate:      CheckTCP,
			produces:  []CheckID{CheckTCP},
			run:       runConnect,
		},
		{
			id:        StageTLS,
			dependsOn: StageConnect,
			produces: []CheckID{
				CheckTLSHandshake, CheckTLSChain,
				CheckTLSHostname, CheckTLSExpiry, CheckTLSVersion,
			},
			run: runTLS,
		},
		{
			id:        StageHTTP,
			dependsOn: StageConnect,
			produces:  []CheckID{CheckHTTP},
			run:       runHTTP,
		},
